threats_l1_candidates:\n[
  {
    "name": "Domestic & Urban Waste Water",
    "desc": "Sewage and urban runoff from housing/settlements: nutrients, toxic chemicals, sediments, pharmaceuticals from municipal systems or domestic sanitation failures. Boundary: if discharge primarily industrial/military use Industrial & Military Effluents. If runoff agricultural/forestry use Agricultural & Forestry Effluents"
  },
  {
    "name": "Industrial & Military Effluents",
    "desc": "Water-borne pollutants from industrial/military activities including mining and energy production: toxic chemicals, heavy metals, hydrocarbons, contaminated sediments, oil spills from pipelines when framed as pollution impact."
  },
  {
    "name": "Agricultural & Forestry Effluents",
    "desc": "Pollution/effluents from agriculture, forestry, aquaculture: nutrients, pesticides, sediments, agrochemicals. Boundary: wind-borne agricultural sediments or smoke use Air-Borne Pollutants. If primary issue is direct conversion to farming use Agriculture & Aquaculture."
  },
  {
    "name": "Garbage & Solid Waste",
    "desc": "Solid waste and debris in environment especially where entangling/ingesting wildlife: municipal litter, roadside trash, marine debris, fishing/boating waste. Boundary: landfills as facilities use Commercial & Industrial Areas. Toxic leachate/chemical seepage use Industrial & Military Effluents."
  },
  {
    "name": "Air-Borne Pollutants",
    "desc": "Atmospheric pollution affecting biodiversity: acid deposition, smog, ozone formation, radioactive fallout, wind dispersion of pollutants/sediments, smoke when framed as air pollution input."
  },
  {
    "name": "Excess Energy",
    "desc": "Non-material pollution where excess energy inputs disturb wildlife/ecosystems: artificial light at night, anthropogenic heat, noise (including underwater noise from sonar/vessels). Examples: light pollution disorienting turtles/insects, thermal discharge from power plants, highway noise affecting bird communication."
  },
  {
    "name": "Annual & Perennial Non-Timber Crops",
    "desc": "Croplands and orchards producing non-timber crops: cereal fields, rice paddies, sugarcane, oil palm, orchards, vineyards, coca. Guidance: if mixed subsistence cropping includes minor livestock, keep here rather than Livestock Farming & Ranching."
  },
  {
    "name": "Wood & Pulp Plantations",
    "desc": "Planted tree stands for timber/fibre on rotation cycles. Key signal: plantation forestry, uniform stands, industrial pulp/timber production. Boundary: if multi-species harvesting in quasi-natural forest (selective logging, enrichment), use Logging & Wood Harvesting. If land conversion to agriculture rather than tree plantations, use Annual & Perennial Non-Timber Crops."
  },
  {
    "name": "Livestock Farming & Ranching",
    "desc": "Domestic terrestrial animal production: feedlots, barns, dairies (farming) or domestic/semi-domesticated animals roaming pastures (ranching/herding). Boundary: if livestock is minor component in subsistence cropping, use Annual & Perennial Non-Timber Crops. If domesticated livestock has gone effectively unmanaged and functions as invasive, consider Invasive Non-Native/Alien Species/Diseases."
  },
  {
    "name": "Marine & Freshwater Aquaculture",
    "desc": "Farming aquatic animals/plants in controlled systems: shrimp/fish farms, fish ponds, cage aquaculture, shellfish beds, algal farms. Boundary: if dominant impact is pollution/effluent discharge rather than farming activity itself, also consider Agricultural & Forestry Effluents."
  },
  {
    "name": "Housing & Urban Areas",
    "desc": "Cities, towns, villages, suburbs, mixed residential areas. Includes peri-urban sprawl, vacation homes, land reclamation for housing. Boundary: if people live there, default here. If primarily industrial/commercial facility with no residential function, use Commercial & Industrial Areas. If dedicated recreation/tourism facility with substantial footprint, use Tourism & Recreation Areas."
  },
  {
    "name": "Commercial & Industrial Areas",
    "desc": "Non-residential built areas with substantial footprint: factories, industrial parks, power plants, shopping centres, airports as facilities, landfills, military bases with permanent footprint. Boundary: dams/hydropower route to Dams & Water Management/Use. Oil/gas pipelines route to Utility & Service Lines."
  },
  {
    "name": "Tourism & Recreation Areas",
    "desc": "Built tourism/recreation sites with substantial footprint: ski areas, resorts, golf courses, campgrounds with permanent infrastructure, sports fields. Boundary: if main issue is disturbance from recreational activity without permanent footprint, use Recreational Activities. Vacation housing primarily for living use Housing & Urban Areas; resort/tourism complex use here."
  }
]

