threats_l1_candidates:\n[
  {
    "name": "Invasive Non-Native/Alien Species/Diseases",
    "desc": "Harmful non-native plants, animals, pathogens introduced intentionally or accidentally by humans AND causing negative ecological impacts on native biodiversity. Includes feral domesticated animals when effectively unmanaged. Boundary: if livestock periodically managed/rounded up as production, use Livestock Farming & Ranching. If little/no management and function as feral/invasive, use here. NEVER use for deliberate reintroductions or translocations of native species within their native range."
  },
  {
    "name": "Problematic Native Species/Diseases",
    "desc": "Native taxa becoming unusually abundant or out-of-balance due to human-driven changes: native species outbreaks, native predators overabundant due to subsidies, native pathogens increasing due to altered conditions. Boundary: if origin clearly non-native use Invasive Non-Native/Alien Species/Diseases. If origin truly unknown use Problematic Species/Diseases of Unknown Origin."
  },
  {
    "name": "Introduced Genetic Material",
    "desc": "Human-altered or transported genetic material affecting native populations via genetic introgression: GMO crops/insects/trees, non-local seed stock in restoration, hatchery-origin fish affecting wild gene pools. Boundary: if non-native organism becomes invasive as a species use Invasive Non-Native/Alien Species/Diseases; if emphasis is genetic mixing/stocking altering gene pools use here."
  },
  {
    "name": "Problematic Species/Diseases of Unknown Origin",
    "desc": "Harmful taxon/pathogen where origin cannot be determined (unclear whether non-native vs native). Use only after attempting to decide between Invasive Non-Native/Alien Species/Diseases and Problematic Native Species/Diseases."
  },
  {
    "name": "Viral/Prion-induced Diseases",
    "desc": "Disease threats where causative agent is specifically a virus or prion: West Nile Virus, Rabies, Foot-and-Mouth Disease, BSE/scrapie."
  },
  {
    "name": "Diseases of Unknown Cause",
    "desc": "Disease syndrome described as a threat but pathogen/agent is unknown. Record disease name and symptoms. Recode once causative agent becomes known"
  },
  {
    "name": "Domestic & Urban Waste Water",
    "desc": "Sewage and urban runoff from housing/settlements: nutrients, toxic chemicals, sediments, pharmaceuticals from municipal systems or domestic sanitation failures. Boundary: if discharge primarily industrial/military use Industrial & Military Effluents. If runoff agricultural/forestry use Agricultural & Forestry Effluents"
  },
  {
    "name": "Industrial & Military Effluents",
    "desc": "Water-borne pollutants from industrial/military activities including mining and energy production: toxic chemicals, heavy metals, hydrocarbons, contaminated sediments, oil spills from pipelines when framed as pollution impact."
  },
  {
    "name": "Agricultural & Forestry Effluents",
    "desc": "Pollution/effluents from agriculture, forestry, aquaculture: nutrients, pesticides, sediments, agrochemicals. Boundary: wind-borne agricultural sediments or smoke use Air-Borne Pollutants. If primary issue is direct conversion to farming use Agriculture & Aquaculture."
  },
  {
    "name": "Garbage & Solid Waste",
    "desc": "Solid waste and debris in environment especially where entangling/ingesting wildlife: municipal litter, roadside trash, marine debris, fishing/boating waste. Boundary: landfills as facilities use Commercial & Industrial Areas. Toxic leachate/chemical seepage use Industrial & Military Effluents."
  },
  {
    "name": "Air-Borne Pollutants",
    "desc": "Atmospheric pollution affecting biodiversity: acid deposition, smog, ozone formation, radioactive fallout, wind dispersion of pollutants/sediments, smoke when framed as air pollution input."
  },
  {
    "name": "Excess Energy",
    "desc": "Non-material pollution where excess energy inputs disturb wildlife/ecosystems: artificial light at night, anthropogenic heat, noise (including underwater noise from sonar/vessels). Examples: light pollution disorienting turtles/insects, thermal discharge from power plants, highway noise affecting bird communication."
  },
  {
    "name": "Habitat Shifting & Alteration",
    "desc": "Climate change primarily alters habitat composition, location, or physical state: sea-level rise, desertification, tundra thaw, coral bleaching, shifting biomes/ecotones."
  },
  {
    "name": "Droughts",
    "desc": "Prolonged rainfall deficits or water scarcity outside normal variation causing ecosystem degradation or species mortality."
  },
  {
    "name": "Temperature Extremes",
    "desc": "Heat/cold extremes outside normal variation: heat waves, cold spells, ocean temperature anomalies, glacier/sea-ice disappearance."
  },
  {
    "name": "Storms & Flooding",
    "desc": "Extreme precipitation/wind events outside normal variation: hurricanes, cyclones, tornadoes, hail/ice storms, blizzards, associated flooding/erosion."
  },
  {
    "name": "Other Impacts",
    "desc": "Climate/severe-weather impacts not covered above: phenological mismatch, increased variability, compound events."
  },
  {
    "name": "Fire & Fire Suppression",
    "desc": "Human-driven changes to fire frequency/intensity outside natural variation (too much fire, too little fire, altered seasonality). Boundary: fire used explicitly to clear NEW land for agriculture, classify conversion under Agriculture & Aquaculture. If text is about ignition sources and management choices affecting fire regime in natural systems, keep here."
  },
  {
    "name": "Dams & Water Management/Use",
    "desc": "Changes to water flow patterns or hydrologic regime: surface/groundwater withdrawal, levees/dikes, channelization, wetland filling, artificial lakes, altered water temperature/volume releases, sediment trapping. Includes hydropower (not Renewable Energy) because defining mechanism is flow alteration. Boundary: dredging for navigation use Shipping Lanes."
  },
  {
    "name": "Other Ecosystem Modifications",
    "desc": "Other human management actions modifying ecosystem structure/processes: land reclamation, shoreline riprap, mowing/thinning, beach construction, removal of snags from streams, habitat abandonment leading to ecological change. Also use for deliberate reintroductions/translocations of native species within their native range when the ecological modification (altered population composition) is the study focus. Boundary: if built development footprint use Residential & Commercial Development. If key mechanism is pollution use Pollution."
  }
]

