threats_l1_candidates:\n[
  {
    "name": "Housing & Urban Areas",
    "desc": "Cities, towns, villages, suburbs, mixed residential areas. Includes peri-urban sprawl, vacation homes, land reclamation for housing. Boundary: if people live there, default here. If primarily industrial/commercial facility with no residential function, use Commercial & Industrial Areas. If dedicated recreation/tourism facility with substantial footprint, use Tourism & Recreation Areas."
  },
  {
    "name": "Commercial & Industrial Areas",
    "desc": "Non-residential built areas with substantial footprint: factories, industrial parks, power plants, shopping centres, airports as facilities, landfills, military bases with permanent footprint. Boundary: dams/hydropower route to Dams & Water Management/Use. Oil/gas pipelines route to Utility & Service Lines."
  },
  {
    "name": "Tourism & Recreation Areas",
    "desc": "Built tourism/recreation sites with substantial footprint: ski areas, resorts, golf courses, campgrounds with permanent infrastructure, sports fields. Boundary: if main issue is disturbance from recreational activity without permanent footprint, use Recreational Activities. Vacation housing primarily for living use Housing & Urban Areas; resort/tourism complex use here."
  },
  {
    "name": "Hunting & Collecting Terrestrial Animals",
    "desc": "Killing/trapping terrestrial wild animals for commercial, subsistence, recreation, research, cultural reasons, or persecution/control; includes accidental mortality. Includes: hunting, trapping, trophy hunting, bushmeat, predator control. Also use when a study describes reintroduction or recovery of a commercially exploited or fur/game species, as prior overexploitation is the implied threat. Semi-aquatic taxa (otters, beavers, amphibians, waterfowl): generally here. Seals, whales, marine mammals, marine turtles: use Fishing & Harvesting Aquatic Resources."
  },
  {
    "name": "Gathering Terrestrial Plants",
    "desc": "Harvesting wild terrestrial plants/fungi: wild mushrooms, medicinal plants, orchid/rattan collection. Boundary: trees/woody vegetation for timber/fibre/fuel use Logging & Wood Harvesting."
  },
  {
    "name": "Logging & Wood Harvesting",
    "desc": "Harvesting trees/woody vegetation from natural/semi-natural systems: clearcutting, selective logging, fuelwood, charcoal, woodchips in quasi-natural forests. Boundary: clearing trees to convert land to agriculture use Agriculture & Aquaculture. Planted timber plantations on rotation use Wood & Pulp Plantations."
  },
  {
    "name": "Fishing & Harvesting Aquatic Resources",
    "desc": "Harvesting wild aquatic animals/plants (freshwater or marine): commercial, subsistence, recreation, persecution/control; includes bycatch. Semi-aquatic distinction: seals, whales, marine mammals, freshwater/marine turtles here; otters/beavers/amphibians/polar bears/penguins/waterfowl/seabirds generally use Hunting & Collecting Terrestrial Animals."
  },
  {
    "name": "Invasive Non-Native/Alien Species/Diseases",
    "desc": "Harmful non-native plants, animals, pathogens introduced intentionally or accidentally by humans AND causing negative ecological impacts on native biodiversity. Includes feral domesticated animals when effectively unmanaged. Boundary: if livestock periodically managed/rounded up as production, use Livestock Farming & Ranching. If little/no management and function as feral/invasive, use here. NEVER use for deliberate reintroductions or translocations of native species within their native range."
  },
  {
    "name": "Problematic Native Species/Diseases",
    "desc": "Native taxa becoming unusually abundant or out-of-balance due to human-driven changes: native species outbreaks, native predators overabundant due to subsidies, native pathogens increasing due to altered conditions. Boundary: if origin clearly non-native use Invasive Non-Native/Alien Species/Diseases. If origin truly unknown use Problematic Species/Diseases of Unknown Origin."
  },
  {
    "name": "Introduced Genetic Material",
    "desc": "Human-altered or transported genetic material affecting native populations via genetic introgression: GMO crops/insects/trees, non-local seed stock in restoration, hatchery-origin fish affecting wild gene pools. Boundary: if non-native organism becomes invasive as a species use Invasive Non-Native/Alien Species/Diseases; if emphasis is genetic mixing/stocking altering gene pools use here."
  },
  {
    "name": "Problematic Species/Diseases of Unknown Origin",
    "desc": "Harmful taxon/pathogen where origin cannot be determined (unclear whether non-native vs native). Use only after attempting to decide between Invasive Non-Native/Alien Species/Diseases and Problematic Native Species/Diseases."
  },
  {
    "name": "Viral/Prion-induced Diseases",
    "desc": "Disease threats where causative agent is specifically a virus or prion: West Nile Virus, Rabies, Foot-and-Mouth Disease, BSE/scrapie."
  },
  {
    "name": "Diseases of Unknown Cause",
    "desc": "Disease syndrome described as a threat but pathogen/agent is unknown. Record disease name and symptoms. Recode once causative agent becomes known"
  }
]

